-- 领取优惠券回滚脚本（MQ 发送失败时调用）
-- KEYS[1]: prs:coupon:{couponId} (优惠券缓存)
-- KEYS[2]: prs:user:coupon:{couponId} (用户领取计数)
-- ARGV[1]: userId
--
-- 返回值: 1-无需回滚(用户计数已为0) 0-回滚成功

-- 1. 防御：仅当用户计数 > 0 时才回滚，防止重复回滚导致计数为负
local cur = tonumber(redis.call('hget', KEYS[2], ARGV[1]) or "0")
if cur <= 0 then
    return 1
end

-- 2. 回滚用户领取计数
redis.call('hincrby', KEYS[2], ARGV[1], -1)

-- 3. 回滚库存
redis.call('hincrby', KEYS[1], "totalNum", 1)

return 0